const https = require('https');

// handle -> { u: gw product url, t: gw product title, s: validated gw sku }
// Generated by build_map.py from automation/globewest-shipping/mapping.json,
// the same validated link the live-freight worker quotes off.
let GW_MAP = {};
try {
  GW_MAP = require('../gw-map.json');
} catch (e) {
  // Deployed without a map: every lookup falls back to the strict search path.
}

// Cache to avoid hammering SearchSpring on every page load
// TTL: 30 minutes
const cache = {};
const CACHE_TTL = 30 * 60 * 1000;

// GlobeWest SearchSpring site ID
const SS_SITE_ID = 'xq8j7f';

/**
 * Convert a Norsu product handle to a GlobeWest search query.
 * Only used for handles missing from GW_MAP.
 */
function handleToQuery(handle) {
  return handle
    .replace(/^copy-of-/, '')
    .replace(/^globewest-/, '')
    .replace(/^globe-west-/, '')
    .replace(/^globe-/, '')
    .replace(/^ethnicraft-/, '')
    .replace(/-copy$/, '')
    .replace(/-([0-9]+)$/, '')
    .replace(/-/g, ' ')
    .trim();
}

function decodeHtmlEntities(str) {
  if (!str) return '';
  return str
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"')
    .replace(/&amp;/g, '&')
    .replace(/&#x27;/g, "'")
    .replace(/&#39;/g, "'");
}

/** Normalise a GW url for identity comparison. */
function normUrl(u) {
  return String(u || '').trim().toLowerCase().replace(/^http:/, 'https:').replace(/\/+$/, '');
}

/** Significant word set of a product name, for the unmapped fallback guard. */
function nameTokens(s) {
  return new Set(
    String(s || '')
      .toLowerCase()
      .replace(/[^a-z0-9]+/g, ' ')
      .split(' ')
      .filter(t => t && t.length > 1)
  );
}

function sameTokens(a, b) {
  const A = nameTokens(a), B = nameTokens(b);
  if (A.size !== B.size) return false;
  for (const t of A) if (!B.has(t)) return false;
  return true;
}

/**
 * Parse the ETA text from GlobeWest's ss_gw_eta_label HTML field.
 * Returns normalised text like "ETA 14/05/26", "In Stock", or "Limited Stock".
 */
function parseEtaLabel(html) {
  if (!html) return null;
  const decoded = decodeHtmlEntities(html);
  const match = decoded.match(/id="eta-data"[^>]*>([^<]+)</) ||
                decoded.match(/class="data"[^>]*>([^<]+)</) ||
                decoded.match(/>([^<]+)</);
  if (!match) return null;
  return match[1].trim().replace(/ETA\s*-\s*/, 'ETA ').trim();
}

function parseStatus(html, etaText) {
  const decoded = decodeHtmlEntities(html || '');
  const lower = String(etaText || '').toLowerCase();
  if (decoded.includes('old-eta-date')) return 'eta';
  if (decoded.includes('old-in-stock')) return 'in_stock';
  if (lower.includes('limited')) return 'limited_stock';
  if (lower.includes('in stock')) return 'in_stock';
  if (lower.includes('eta')) return 'eta';
  return 'unknown';
}

function parseDate(etaText) {
  if (!etaText) return null;
  const m = String(etaText).match(/(\d{1,2})\/(\d{1,2})\/(\d{2,4})/);
  if (!m) return null;
  const day = m[1].padStart(2, '0');
  const month = m[2].padStart(2, '0');
  const year = m[3].length === 2 ? '20' + m[3] : m[3];
  return `${year}-${month}-${day}`;
}

function get(options, timeoutMs) {
  return new Promise((resolve, reject) => {
    const req = https.request(options, (res) => {
      if ([301, 302, 307, 308].includes(res.statusCode) && res.headers.location) {
        res.resume();
        try {
          const next = new URL(res.headers.location, `https://${options.hostname}`);
          return resolve(get({
            hostname: next.hostname,
            path: next.pathname + next.search,
            method: 'GET',
            headers: options.headers,
          }, timeoutMs));
        } catch (e) {
          return reject(e);
        }
      }
      let data = '';
      res.on('data', c => { data += c; });
      res.on('end', () => resolve(data));
    });
    req.on('error', reject);
    req.setTimeout(timeoutMs, () => { req.destroy(); reject(new Error('timeout')); });
    req.end();
  });
}

/** Query SearchSpring and return the raw result array. */
async function searchSpring(query, perPage) {
  const path = `/api/search/search.json?siteId=${SS_SITE_ID}` +
               `&q=${encodeURIComponent(query)}&resultsFormat=native&resultsPerPage=${perPage}`;
  const body = await get({
    hostname: 'api.searchspring.net',
    path,
    method: 'GET',
    headers: {
      'User-Agent': 'Mozilla/5.0 (compatible; NorsuETA/2.0)',
      'Accept': 'application/json',
    },
  }, 8000);
  const json = JSON.parse(body);
  const results = json.results;
  return Array.isArray(results) ? results : [];
}

/**
 * Last resort for a pinned product SearchSpring won't return: read the GW
 * product page and parse its own eta container, which is the source of truth.
 */
async function etaFromPage(url) {
  const u = new URL(url);
  const html = await get({
    hostname: u.hostname,
    path: u.pathname + u.search,
    method: 'GET',
    headers: {
      'User-Agent': 'Mozilla/5.0 (compatible; NorsuETA/2.0)',
      'Accept': 'text/html',
    },
  }, 10000);
  if (/<title>404|404 Not Found/.test(html.slice(0, 3000))) return null;
  const m = html.match(/product-eta-container\s+([a-z\-]*)"[^>]*>[\s\S]*?id="eta-data"[^>]*>([^<]*)</);
  if (!m) return null;
  const cls = m[1] || '';
  const text = m[2].trim().replace(/ETA\s*-\s*/, 'ETA ');
  if (!text) return null;
  const lower = text.toLowerCase();
  const status = cls.includes('in-stock') ? 'in_stock'
    : cls.includes('limited') || lower.includes('limited') ? 'limited_stock'
    : cls.includes('eta') || lower.includes('eta') ? 'eta'
    : lower.includes('in stock') ? 'in_stock'
    : 'unknown';
  return { etaText: text, status };
}

/**
 * Resolve a handle to { name, etaText, status, url, matched }.
 *
 * Pinned handles are only ever answered from the exact GW product the freight
 * mapping validated. If that product can't be retrieved we return unknown so
 * the badge hides -- showing a neighbouring product's stock is worse than
 * showing nothing.
 */
async function resolve(handle) {
  const pin = GW_MAP[handle];

  if (pin) {
    // Ask by the GW product's own name, then accept ONLY the exact url.
    let results = [];
    try {
      results = await searchSpring(pin.t, 25);
    } catch (e) { /* fall through to the page read */ }
    const hit = results.find(r => normUrl(r.url) === normUrl(pin.u));
    if (hit) {
      const etaText = parseEtaLabel(hit.ss_gw_eta_label || '');
      return {
        name: hit.name || pin.t,
        etaText,
        status: parseStatus(hit.ss_gw_eta_label || '', etaText),
        url: hit.url,
        matched: 'pinned',
      };
    }
    try {
      const page = await etaFromPage(pin.u);
      if (page) {
        return {
          name: pin.t, etaText: page.etaText, status: page.status,
          url: pin.u, matched: 'pinned-page',
        };
      }
    } catch (e) { /* hide below */ }
    return { name: pin.t, etaText: null, status: 'unknown', url: pin.u, matched: 'pinned-miss' };
  }

  // Unmapped handle: only trust a result whose name matches word-for-word.
  const query = handleToQuery(handle);
  const results = await searchSpring(query, 10);
  const exact = results.find(r => sameTokens(r.name || r.title, query));
  if (!exact) {
    return { name: null, etaText: null, status: 'unknown', url: null, matched: 'unmapped-no-exact' };
  }
  const etaText = parseEtaLabel(exact.ss_gw_eta_label || '');
  return {
    name: exact.name || exact.title || '',
    etaText,
    status: parseStatus(exact.ss_gw_eta_label || '', etaText),
    url: exact.url,
    matched: 'unmapped-exact',
  };
}

module.exports = async function handler(req, res) {
  res.setHeader('Access-Control-Allow-Origin', '*');
  res.setHeader('Access-Control-Allow-Methods', 'GET, OPTIONS');
  res.setHeader('Access-Control-Allow-Headers', 'Content-Type');

  if (req.method === 'OPTIONS') {
    return res.status(200).end();
  }

  const handle = (req.query.handle || '').toLowerCase().trim();
  if (!handle) {
    return res.status(400).json({ error: 'Missing handle parameter' });
  }

  const now = Date.now();
  if (cache[handle] && (now - cache[handle].ts) < CACHE_TTL) {
    return res.status(200).json({ ...cache[handle].data, cached: true });
  }

  try {
    const r = await resolve(handle);
    const data = {
      handle,
      name: r.name,
      eta_text: r.etaText,
      eta_date: parseDate(r.etaText),
      status: r.status,
      source_url: r.url,
      matched: r.matched,
      fetched_at: new Date().toISOString(),
    };
    cache[handle] = { data, ts: now };
    return res.status(200).json({ ...data, cached: false });
  } catch (err) {
    return res.status(200).json({
      handle,
      error: err.message,
      eta_text: null,
      status: 'unknown',
    });
  }
};
